mapper.select:
SELECT DATE(visit_time) as visitDate, COUNT(*) as totalViews, COUNT(DISTINCT visitor_id) as uniqueVisitors, COUNT(DISTINCT ip_address) as uniqueIps, COUNT(CASE WHEN device_type = 'Mobile' THEN 1 END) as mobileViews, COUNT(CASE WHEN device_type = 'PC' THEN 1 END) as pcViews, COUNT(CASE WHEN device_type = 'Tablet' THEN 1 END) as tabletViews FROM t_page_view_log WHERE agent_code = #{agentCode}
AND visit_time >= #{startDate}
AND visit_time <= #{endDate}
GROUP BY DATE(visit_time) ORDER BY visitDate DESC
